from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing each square in a thread pool.

    The result preserves the order of the input list.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(square, xs))


@pytest.mark.parametrize(
    ("xs", "expected"),
    [
        ([], []),
        ([0], [0]),
        ([3], [9]),
        ([-3, 0, 2], [9, 0, 4]),
        ([1, 1, 1], [1, 1, 1]),
    ],
)
def test_squares_small(xs: list[int], expected: list[int]) -> None:
    assert squares(xs) == expected


def test_squares_preserves_order() -> None:
    xs = list(range(1000))
    assert squares(xs) == [square(x) for x in xs]


def test_squares_length_matches_input() -> None:
    xs = [5, -2, 7, 7, 0]
    assert len(squares(xs)) == len(xs)
